insert into public.profiles (slug,display_name,first_name,photo_url,hero_url,logo_url,socials,published) values ('louis','Louis Delétraz','Louis','https://birel22.github.io/louis-calendar/car.jpg','https://birel22.github.io/louis-calendar/car.jpg','https://birel22.github.io/louis-calendar/logo.png','{"instagram": "https://www.instagram.com/louisdeletraz/", "facebook": "https://www.facebook.com/l.deletraz/", "x": "https://x.com/LouisDeletraz", "youtube": "https://www.youtube.com/@LouisDel%C3%A9traz-h7t", "website": "https://louisdeletraz.com"}'::jsonb,true) on conflict (slug) do nothing;
insert into public.subscriptions (profile_id,status,provider) select id,'active','manual' from public.profiles where slug='louis' on conflict (profile_id) do nothing;
insert into public.entries (profile_id,series_id,year,team,car_number,category,vehicle_id,teammates,color) select (select id from public.profiles where slug='louis'),(select id from public.series where slug='alms'),2027,'CrowdStrike by APR','4','LMP2',(select id from public.vehicles where name='ORECA 07'),'{"Laurin Heinrich","George Kurtz"}','#5FCF6E' on conflict (profile_id,series_id,year) do nothing;
