insert into public.sponsors (profile_id,name,logo_original_url,logo_white_url,display,link_url,sort) select id,'Cadillac','https://birel22.github.io/louis-calendar/cadillac.png','https://birel22.github.io/louis-calendar/cadillac.png','white','https://www.cadillac.com/racing',0 from public.profiles where slug='louis' and not exists (select 1 from public.sponsors s join public.profiles p on p.id=s.profile_id where p.slug='louis' and s.name='Cadillac');
